SELECT id, base_id, region_scope, policy_group, policy_name, policy_aliases, policy_no,
       policy_type, topic_tags, short_summary, source_doc_type, source_doc_name,
       source_chunk_ids, searchable, sort_order, create_time, update_time
FROM ai_policy_catalog
WHERE base_id = #{baseId}

    AND region_scope = #{regionScope}


    AND searchable = #{searchable}

ORDER BY sort_order ASC, policy_name ASC
